// ── Utility Functions ─────────────────────────────────────────────────

export function getTNMLAByConstituency(acNo: number): LegislatorProfile | undefined {
  return TN_MLA_PROFILES.find(p => p.acNo === acNo);
}

export function getTNMLAByName(name: string): LegislatorProfile | undefined {
  const q = name.toLowerCase();
  return TN_MLA_PROFILES.find(p =>
    p.name.toLowerCase().includes(q) || p.displayName?.toLowerCase().includes(q)
  );
}

export function getTNMLAsByParty(party: string): LegislatorProfile[] {
  return TN_MLA_PROFILES.filter(p => p.currentParty === party);
}

export function getTNFemaleMLAs(): LegislatorProfile[] {
  return TN_MLA_PROFILES.filter(p => p.gender === 'F');
}

export function getTNCrorepatiMLAs(): LegislatorProfile[] {
  return TN_MLA_PROFILES.filter(p =>
    p.financialHistory.some(f => f.isCrorepati)
  );
}

export function getTNMLAsWithCriminalCases(): LegislatorProfile[] {
  return TN_MLA_PROFILES.filter(p => p.criminalRecord.hasCriminalCases);
}

export function getTNMultiTermMLAs(): LegislatorProfile[] {
  return TN_MLA_PROFILES.filter(p => p.termsServed >= 2);
}

export function getTNPartyStrength(): Record<string, number> {
  const strength: Record<string, number> = {};
  for (const p of TN_MLA_PROFILES) {
    strength[p.currentParty] = (strength[p.currentParty] || 0) + 1;
  }
  return strength;
}

export function getTNWealthStats() {
  const sorted = [...TN_MLA_PROFILES]
    .filter(p => p.financialHistory[0]?.totalAssets > 0)
    .sort((a, b) => (b.financialHistory[0]?.totalAssets || 0) - (a.financialHistory[0]?.totalAssets || 0));
  return {
    richest: sorted[0],
    poorest: sorted[sorted.length - 1],
    totalMLAs: sorted.length,
    crorepatis: sorted.filter(p => p.financialHistory[0]?.isCrorepati).length,
    avgNetWorth: sorted.reduce((s, p) => s + (p.financialHistory[0]?.netWorth || 0), 0) / sorted.length,
  };
}

export function getTNMLAProfile(acNo: number): LegislatorProfile | undefined {
  return getTNMLAByConstituency(acNo);
}
export function getAllTNMLAs(): LegislatorProfile[] {
  return TN_MLA_PROFILES;
}
